#include <memory>
#include <stdexcept>
#include <vector>

class IntList
{
public:
    void push_front(int value) {}
    void push_back(int value) {}
    int pop_front() { return 0; }
    std::size_t size() const { return 0; }
    bool empty() const { return true; }
    std::vector<int> toVector() const { return {}; }
    void reverse() {}
    std::size_t removeAll(int value) { return 0; }
    bool hasValue(int value) const { return false; }
    int middle() const { return 0; }

private:
    struct Node
    {
        int value;
        std::unique_ptr<Node> next;
    };
    std::unique_ptr<Node> head_;
    Node* tail_ = nullptr;
    std::size_t size_ = 0;
};

solution.solution.cpp:
#include <memory>
#include <stdexcept>
#include <vector>

class IntList
{
public:
    IntList() = default;
    IntList(const IntList&) = delete;
    IntList& operator=(const IntList&) = delete;

    ~IntList()
    {
        while (head_) head_ = std::move(head_->next);
    }

    void push_front(int value)
    {
        head_ = std::make_unique<Node>(Node{ value, std::move(head_) });
        if (!tail_) tail_ = head_.get();
        ++size_;
    }

    void push_back(int value)
    {
        auto node = std::make_unique<Node>(Node{ value, nullptr });
        Node* raw = node.get();
        if (tail_) tail_->next = std::move(node); else head_ = std::move(node);
        tail_ = raw;
        ++size_;
    }

    int pop_front()
    {
        if (!head_) throw std::out_of_range("pop_front on an empty list");
        int value = head_->value;
        head_ = std::move(head_->next);
        if (!head_) tail_ = nullptr;
        --size_;
        return value;
    }

    std::size_t size() const { return size_; }
    bool empty() const { return size_ == 0; }

    std::vector<int> toVector() const
    {
        std::vector<int> out;
        out.reserve(size_);
        for (const Node* n = head_.get(); n; n = n->next.get()) out.push_back(n->value);
        return out;
    }

    void reverse()
    {
        tail_ = head_.get();
        std::unique_ptr<Node> previous;
        while (head_)
        {
            std::unique_ptr<Node> next = std::move(head_->next);
            head_->next = std::move(previous);
            previous = std::move(head_);
            head_ = std::move(next);
        }
        head_ = std::move(previous);
    }

    std::size_t removeAll(int value)
    {
        std::size_t removed = 0;
        std::unique_ptr<Node>* link = &head_;
        tail_ = nullptr;
        while (*link)
        {
            if ((*link)->value == value)
            {
                *link = std::move((*link)->next);
                ++removed;
            }
            else
            {
                tail_ = link->get();
                link = &(*link)->next;
            }
        }
        size_ -= removed;
        return removed;
    }

    bool hasValue(int value) const
    {
        for (const Node* n = head_.get(); n; n = n->next.get())
            if (n->value == value) return true;
        return false;
    }

    int middle() const
    {
        if (!head_) throw std::out_of_range("middle of an empty list");
        const Node* slow = head_.get();
        const Node* fast = head_.get();
        while (fast && fast->next)
        {
            slow = slow->next.get();
            fast = fast->next->next.get();
        }
        return slow->value;
    }

private:
    struct Node
    {
        int value;
        std::unique_ptr<Node> next;
    };
    std::unique_ptr<Node> head_;
    Node* tail_ = nullptr;
    std::size_t size_ = 0;
};

unitTests:
using V = std::vector<int>;

TEST("both ends") {
    IntList list;
    CHECK(list.empty());
    list.push_back(2);
    list.push_front(1);
    list.push_back(3);
    CHECK_EQ(list.toVector(), (V{ 1, 2, 3 }));
    CHECK_EQ(list.size(), std::size_t{ 3 });
    CHECK_EQ(list.pop_front(), 1);
    CHECK_EQ(list.pop_front(), 2);
    CHECK_EQ(list.pop_front(), 3);
    CHECK(list.empty());
    CHECK_THROWS(list.pop_front());
    list.push_back(9);                       // the tail must have been reset
    CHECK_EQ(list.toVector(), (V{ 9 }));
}
TEST("reverse") {
    IntList list;
    for (int i = 1; i <= 5; ++i) list.push_back(i);
    list.reverse();
    CHECK_EQ(list.toVector(), (V{ 5, 4, 3, 2, 1 }));
    list.push_back(0);
    CHECK_EQ(list.toVector(), (V{ 5, 4, 3, 2, 1, 0 }));
    IntList empty;
    empty.reverse();
    CHECK(empty.empty());
}
TEST("remove every match") {
    IntList list;
    for (int x : { 7, 1, 7, 7, 2, 7 }) list.push_back(x);
    CHECK_EQ(list.removeAll(7), std::size_t{ 4 });
    CHECK_EQ(list.toVector(), (V{ 1, 2 }));
    CHECK_EQ(list.size(), std::size_t{ 2 });
    list.push_back(3);
    CHECK_EQ(list.toVector(), (V{ 1, 2, 3 }));
    CHECK_EQ(list.removeAll(42), std::size_t{ 0 });
    CHECK(list.hasValue(2));
    CHECK(!list.hasValue(7));
    list.removeAll(1); list.removeAll(2); list.removeAll(3);
    CHECK(list.empty());
    list.push_back(4);
    CHECK_EQ(list.toVector(), (V{ 4 }));
}
TEST("middle") {
    IntList list;
    CHECK_THROWS(list.middle());
    list.push_back(10);
    CHECK_EQ(list.middle(), 10);
    for (int x : { 20, 30, 40, 50 }) list.push_back(x);
    CHECK_EQ(list.middle(), 30);
    list.push_back(60);
    CHECK_EQ(list.middle(), 40);
}
TEST("a million nodes") {
    {
        IntList list;
        for (int i = 0; i < 1000000; ++i) list.push_front(i);
        CHECK_EQ(list.size(), std::size_t{ 1000000 });
    }   // the destructor must not recurse a million levels deep
    CHECK(true);
}
TEST("no leaks") {
    CHECK_NO_LEAK({ IntList l; for (int i = 0; i < 100; ++i) l.push_back(i % 5); l.removeAll(3); l.reverse(); l.pop_front(); });
}

